-- Disposable bounded read summaries; immutable evidence, selection audit and identity are retained.
-- Live selection/link changes refresh summaries atomically, including deletions/moves.
-- Quality holds/conflicts and all proof/time gates remain live on reads.
CREATE TABLE customer_selection_heads(entity_id TEXT PRIMARY KEY REFERENCES entities(id),fields_json TEXT NOT NULL CHECK(json_valid(fields_json)),selected_record_ids_json TEXT NOT NULL CHECK(json_valid(selected_record_ids_json)));
CREATE TRIGGER customer_selection_heads_insert_guard BEFORE INSERT ON customer_selection_heads WHEN NOT (NEW.fields_json IS (SELECT json_group_object(f.field_name,json(f.value_json)) FROM selected_facts f WHERE f.entity_id=NEW.entity_id) AND NEW.selected_record_ids_json IS (SELECT json_group_array(f.record_id) FROM selected_facts f WHERE f.entity_id=NEW.entity_id)) BEGIN SELECT RAISE(ABORT,'source_bound_selection_head_required'); END;
CREATE TRIGGER customer_selection_heads_update_guard BEFORE UPDATE ON customer_selection_heads WHEN NEW.entity_id<>OLD.entity_id OR NOT (NEW.fields_json IS (SELECT json_group_object(f.field_name,json(f.value_json)) FROM selected_facts f WHERE f.entity_id=NEW.entity_id) AND NEW.selected_record_ids_json IS (SELECT json_group_array(f.record_id) FROM selected_facts f WHERE f.entity_id=NEW.entity_id)) BEGIN SELECT RAISE(ABORT,'source_bound_selection_head_required'); END;
CREATE TRIGGER field_selections_refresh_customer_insert AFTER INSERT ON field_selections BEGIN INSERT INTO customer_selection_heads(entity_id,fields_json,selected_record_ids_json) VALUES(NEW.entity_id,(SELECT json_group_object(f.field_name,json(f.value_json)) FROM selected_facts f WHERE f.entity_id=NEW.entity_id),(SELECT json_group_array(f.record_id) FROM selected_facts f WHERE f.entity_id=NEW.entity_id)) ON CONFLICT(entity_id) DO UPDATE SET fields_json=excluded.fields_json,selected_record_ids_json=excluded.selected_record_ids_json; END;
CREATE TRIGGER field_selections_refresh_customer_update AFTER UPDATE ON field_selections BEGIN INSERT INTO customer_selection_heads(entity_id,fields_json,selected_record_ids_json) VALUES(OLD.entity_id,(SELECT json_group_object(f.field_name,json(f.value_json)) FROM selected_facts f WHERE f.entity_id=OLD.entity_id),(SELECT json_group_array(f.record_id) FROM selected_facts f WHERE f.entity_id=OLD.entity_id)) ON CONFLICT(entity_id) DO UPDATE SET fields_json=excluded.fields_json,selected_record_ids_json=excluded.selected_record_ids_json;INSERT INTO customer_selection_heads(entity_id,fields_json,selected_record_ids_json) VALUES(NEW.entity_id,(SELECT json_group_object(f.field_name,json(f.value_json)) FROM selected_facts f WHERE f.entity_id=NEW.entity_id),(SELECT json_group_array(f.record_id) FROM selected_facts f WHERE f.entity_id=NEW.entity_id)) ON CONFLICT(entity_id) DO UPDATE SET fields_json=excluded.fields_json,selected_record_ids_json=excluded.selected_record_ids_json; END;
CREATE TRIGGER field_selections_refresh_customer_delete AFTER DELETE ON field_selections BEGIN INSERT INTO customer_selection_heads(entity_id,fields_json,selected_record_ids_json) VALUES(OLD.entity_id,(SELECT json_group_object(f.field_name,json(f.value_json)) FROM selected_facts f WHERE f.entity_id=OLD.entity_id),(SELECT json_group_array(f.record_id) FROM selected_facts f WHERE f.entity_id=OLD.entity_id)) ON CONFLICT(entity_id) DO UPDATE SET fields_json=excluded.fields_json,selected_record_ids_json=excluded.selected_record_ids_json; END;
INSERT INTO customer_selection_heads(entity_id,fields_json,selected_record_ids_json) SELECT e.id,(SELECT json_group_object(f.field_name,json(f.value_json)) FROM selected_facts f WHERE f.entity_id=e.id),(SELECT json_group_array(f.record_id) FROM selected_facts f WHERE f.entity_id=e.id) FROM entities e;
CREATE TABLE customer_origin_heads(entity_id TEXT PRIMARY KEY REFERENCES entities(id),producers_json TEXT NOT NULL CHECK(json_valid(producers_json)),origin TEXT);
CREATE TRIGGER customer_origin_heads_insert_guard BEFORE INSERT ON customer_origin_heads WHEN NOT (NEW.producers_json IS (SELECT json_group_array(DISTINCT p.producer_name) FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')) AND NEW.origin IS (SELECT p.producer_name FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.validation_status='accepted' AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')
  AND COALESCE(json_extract(p.normalized_json,'$.provenance.diagnostic'),0)<>1 AND COALESCE(json_extract(p.normalized_json,'$.provenance[0].diagnostic'),0)<>1
  ORDER BY p.received_at,p.id LIMIT 1)) BEGIN SELECT RAISE(ABORT,'source_bound_selection_head_required'); END;
CREATE TRIGGER customer_origin_heads_update_guard BEFORE UPDATE ON customer_origin_heads WHEN NEW.entity_id<>OLD.entity_id OR NOT (NEW.producers_json IS (SELECT json_group_array(DISTINCT p.producer_name) FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')) AND NEW.origin IS (SELECT p.producer_name FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.validation_status='accepted' AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')
  AND COALESCE(json_extract(p.normalized_json,'$.provenance.diagnostic'),0)<>1 AND COALESCE(json_extract(p.normalized_json,'$.provenance[0].diagnostic'),0)<>1
  ORDER BY p.received_at,p.id LIMIT 1)) BEGIN SELECT RAISE(ABORT,'source_bound_selection_head_required'); END;
CREATE TRIGGER entity_records_refresh_customer_insert AFTER INSERT ON entity_records BEGIN INSERT INTO customer_origin_heads(entity_id,producers_json,origin) VALUES(NEW.entity_id,(SELECT json_group_array(DISTINCT p.producer_name) FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')),(SELECT p.producer_name FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.validation_status='accepted' AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')
  AND COALESCE(json_extract(p.normalized_json,'$.provenance.diagnostic'),0)<>1 AND COALESCE(json_extract(p.normalized_json,'$.provenance[0].diagnostic'),0)<>1
  ORDER BY p.received_at,p.id LIMIT 1)) ON CONFLICT(entity_id) DO UPDATE SET producers_json=excluded.producers_json,origin=excluded.origin; END;
CREATE TRIGGER entity_records_refresh_customer_update AFTER UPDATE ON entity_records BEGIN INSERT INTO customer_origin_heads(entity_id,producers_json,origin) VALUES(OLD.entity_id,(SELECT json_group_array(DISTINCT p.producer_name) FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=OLD.entity_id AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')),(SELECT p.producer_name FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=OLD.entity_id AND p.validation_status='accepted' AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')
  AND COALESCE(json_extract(p.normalized_json,'$.provenance.diagnostic'),0)<>1 AND COALESCE(json_extract(p.normalized_json,'$.provenance[0].diagnostic'),0)<>1
  ORDER BY p.received_at,p.id LIMIT 1)) ON CONFLICT(entity_id) DO UPDATE SET producers_json=excluded.producers_json,origin=excluded.origin;INSERT INTO customer_origin_heads(entity_id,producers_json,origin) VALUES(NEW.entity_id,(SELECT json_group_array(DISTINCT p.producer_name) FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')),(SELECT p.producer_name FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=NEW.entity_id AND p.validation_status='accepted' AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')
  AND COALESCE(json_extract(p.normalized_json,'$.provenance.diagnostic'),0)<>1 AND COALESCE(json_extract(p.normalized_json,'$.provenance[0].diagnostic'),0)<>1
  ORDER BY p.received_at,p.id LIMIT 1)) ON CONFLICT(entity_id) DO UPDATE SET producers_json=excluded.producers_json,origin=excluded.origin; END;
CREATE TRIGGER entity_records_refresh_customer_delete AFTER DELETE ON entity_records BEGIN INSERT INTO customer_origin_heads(entity_id,producers_json,origin) VALUES(OLD.entity_id,(SELECT json_group_array(DISTINCT p.producer_name) FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=OLD.entity_id AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')),(SELECT p.producer_name FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=OLD.entity_id AND p.validation_status='accepted' AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')
  AND COALESCE(json_extract(p.normalized_json,'$.provenance.diagnostic'),0)<>1 AND COALESCE(json_extract(p.normalized_json,'$.provenance[0].diagnostic'),0)<>1
  ORDER BY p.received_at,p.id LIMIT 1)) ON CONFLICT(entity_id) DO UPDATE SET producers_json=excluded.producers_json,origin=excluded.origin; END;
INSERT INTO customer_origin_heads(entity_id,producers_json,origin) SELECT e.id,(SELECT json_group_array(DISTINCT p.producer_name) FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=e.id AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')),(SELECT p.producer_name FROM entity_records er JOIN producer_records p ON p.id=er.record_id WHERE er.entity_id=e.id AND p.validation_status='accepted' AND p.producer_name IN ('independent-structured','legacy_v2','city-search','source-led-search','platform-catalogue','uk-official','legacy-global-uk','legacy_mk1')
  AND COALESCE(json_extract(p.normalized_json,'$.provenance.diagnostic'),0)<>1 AND COALESCE(json_extract(p.normalized_json,'$.provenance[0].diagnostic'),0)<>1
  ORDER BY p.received_at,p.id LIMIT 1) FROM entities e;
